"use client";

import * as React from "react";
import { Combobox as ComboboxPrimitive } from "@base-ui/react";
import { cn } from "@/lib/utils";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
} from "@/components/ui/input-group";
import { ArrowDown01Icon, Cancel01Icon, Tick02Icon } from "@hugeicons/core-free-icons";
import { HaloIcon } from "@/components/icons/halo-icon";

/**
 * Combobox — Forms & Fields Primitive
 *
 * An accessible searchable option picker for selecting one value
 * from a filterable collection, styled with HaloUI's 10-layer
 * optical liquid glass engine.
 */
const Combobox = ComboboxPrimitive.Root;

function ComboboxValue({ ...props }: ComboboxPrimitive.Value.Props) {
  return <ComboboxPrimitive.Value data-slot="combobox-value" {...props} />;
}

function ComboboxTrigger({
  className,
  children,
  ...props
}: ComboboxPrimitive.Trigger.Props) {
  return (
    <ComboboxPrimitive.Trigger
      data-slot="combobox-trigger"
      className={cn("flex size-7 items-center justify-center text-muted-foreground select-none", className)}
      {...props}
    >
      {children}
      <HaloIcon icon={ArrowDown01Icon} size={15} />
    </ComboboxPrimitive.Trigger>
  );
}

function ComboboxClear({ className, ...props }: ComboboxPrimitive.Clear.Props) {
  return (
    <ComboboxPrimitive.Clear
      data-slot="combobox-clear"
      render={<InputGroupButton variant="ghost" size="icon-xs" />}
      className={cn(className)}
      {...props}
    >
      <HaloIcon icon={Cancel01Icon} size={14} className="pointer-events-none" />
    </ComboboxPrimitive.Clear>
  );
}

export interface ComboboxInputProps extends ComboboxPrimitive.Input.Props {
  showTrigger?: boolean;
  showClear?: boolean;
}

function ComboboxInput({
  className,
  children,
  disabled = false,
  showTrigger = true,
  showClear = false,
  ...props
}: ComboboxInputProps) {
  return (
    <InputGroup className={cn("w-full", className)}>
      <ComboboxPrimitive.Input
        render={<InputGroupInput disabled={disabled} />}
        {...props}
      />
      <InputGroupAddon align="inline-end">
        {showTrigger && (
          <InputGroupButton
            size="icon-xs"
            variant="ghost"
            render={<ComboboxTrigger />}
            data-slot="input-group-button"
            className="group-has-data-[slot=combobox-clear]/input-group:hidden data-pressed:bg-transparent"
            disabled={disabled}
          />
        )}
        {showClear && <ComboboxClear disabled={disabled} />}
      </InputGroupAddon>
      {children}
    </InputGroup>
  );
}

function ComboboxContent({
  className,
  side = "bottom",
  sideOffset = 6,
  align = "start",
  alignOffset = 0,
  anchor,
  children,
  ...props
}: ComboboxPrimitive.Popup.Props &
  Pick<
    ComboboxPrimitive.Positioner.Props,
    "side" | "align" | "sideOffset" | "alignOffset" | "anchor"
  >) {
  return (
    <ComboboxPrimitive.Portal>
      <ComboboxPrimitive.Positioner
        side={side}
        sideOffset={sideOffset}
        align={align}
        alignOffset={alignOffset}
        anchor={anchor}
        className="isolate z-50"
      >
        <ComboboxPrimitive.Popup
          data-slot="combobox-content"
          className={cn(
            // HaloUI Physical Liquid Glass Engine (Button Specification with elevated backdrop opacity)
            "halo-liquid-glass relative isolate z-50 max-h-(--available-height) min-w-(--anchor-width) w-auto max-w-sm origin-(--transform-origin) overflow-hidden rounded-2xl p-1.5 text-foreground outline-none",
            "!bg-white/85 dark:!bg-neutral-950/80 !backdrop-blur-2xl !backdrop-saturate-200",
            // Micro animation
            "duration-150 data-[side=bottom]:slide-in-from-top-1.5 data-[side=top]:slide-in-from-bottom-1.5 data-open:animate-in data-open:fade-in-0 data-open:zoom-in-98 data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-98",
            className
          )}
          {...props}
        >
          <div className="relative z-10">{children}</div>
        </ComboboxPrimitive.Popup>
      </ComboboxPrimitive.Positioner>
    </ComboboxPrimitive.Portal>
  );
}

function ComboboxList({ className, ...props }: ComboboxPrimitive.List.Props) {
  return (
    <ComboboxPrimitive.List
      data-slot="combobox-list"
      className={cn(
        "max-h-60 overflow-y-auto overscroll-contain p-0.5 space-y-0.5 outline-none",
        className
      )}
      {...props}
    />
  );
}

function ComboboxItem({
  className,
  children,
  ...props
}: ComboboxPrimitive.Item.Props) {
  return (
    <ComboboxPrimitive.Item
      data-slot="combobox-item"
      className={cn(
        "relative flex w-full cursor-pointer items-center justify-between gap-2 rounded-xl py-2 pl-3 pr-8 text-sm outline-none select-none transition-all duration-150",
        // Active roving focus state: frosted glass highlight
        "data-highlighted:bg-white/80 dark:data-highlighted:bg-white/[0.14] data-highlighted:backdrop-blur-md",
        "data-highlighted:shadow-[inset_0_1px_1px_0_rgba(255,255,255,0.95),0_1px_3px_0_rgba(0,0,0,0.06)]",
        "dark:data-highlighted:shadow-[inset_0_1px_1px_0_rgba(255,255,255,0.22),0_2px_6px_0_rgba(0,0,0,0.4)]",
        "data-highlighted:text-foreground",
        // Selected committed state
        "data-selected:font-medium data-selected:text-foreground",
        // Disabled option
        "data-disabled:pointer-events-none data-disabled:cursor-not-allowed data-disabled:opacity-35",
        className
      )}
      {...props}
    >
      <span className="flex flex-1 items-center gap-2 truncate">{children}</span>
      <ComboboxPrimitive.ItemIndicator
        render={
          <span className="pointer-events-none absolute right-2.5 flex size-4 items-center justify-center text-primary drop-shadow-[0_0_8px_rgba(var(--primary),0.4)]">
            <HaloIcon icon={Tick02Icon} size={15} />
          </span>
        }
      />
    </ComboboxPrimitive.Item>
  );
}

function ComboboxGroup({ className, ...props }: ComboboxPrimitive.Group.Props) {
  return (
    <ComboboxPrimitive.Group
      data-slot="combobox-group"
      className={cn("p-1", className)}
      {...props}
    />
  );
}

function ComboboxLabel({
  className,
  ...props
}: ComboboxPrimitive.GroupLabel.Props) {
  return (
    <ComboboxPrimitive.GroupLabel
      data-slot="combobox-label"
      className={cn("px-2.5 py-1.5 text-xs font-semibold uppercase tracking-wider text-muted-foreground select-none", className)}
      {...props}
    />
  );
}

function ComboboxCollection({ ...props }: ComboboxPrimitive.Collection.Props) {
  return (
    <ComboboxPrimitive.Collection data-slot="combobox-collection" {...props} />
  );
}

function ComboboxEmpty({ className, ...props }: ComboboxPrimitive.Empty.Props) {
  return (
    <ComboboxPrimitive.Empty
      data-slot="combobox-empty"
      className={cn(
        "py-6 text-center text-sm text-muted-foreground select-none",
        className
      )}
      {...props}
    />
  );
}

function ComboboxSeparator({
  className,
  ...props
}: ComboboxPrimitive.Separator.Props) {
  return (
    <ComboboxPrimitive.Separator
      data-slot="combobox-separator"
      className={cn("pointer-events-none -mx-1 my-1 h-px bg-black/[0.08] dark:bg-white/[0.08]", className)}
      {...props}
    />
  );
}

export {
  Combobox,
  ComboboxInput,
  ComboboxContent,
  ComboboxList,
  ComboboxItem,
  ComboboxGroup,
  ComboboxLabel,
  ComboboxCollection,
  ComboboxEmpty,
  ComboboxSeparator,
  ComboboxTrigger,
  ComboboxClear,
  ComboboxValue,
};

export default Combobox;

"use client";

import * as React from "react";
import { HugeiconsIcon } from "@hugeicons/react";
import type { IconSvgElement } from "@hugeicons/react";
import { cn } from "@/lib/utils";

export type IconSize = "xs" | "sm" | "md" | "lg" | "xl" | number;

const sizeMap: Record<string, number> = {
  xs: 14,
  sm: 16,
  md: 18,
  lg: 20,
  xl: 24,
};

export interface HaloIconProps extends Omit<React.SVGProps<SVGSVGElement>, "color" | "strokeWidth" | "size"> {
  icon: IconSvgElement;
  size?: IconSize;
  strokeWidth?: number;
  className?: string;
  color?: string;
}

/**
 * Standardized HaloUI Icon wrapper using Hugeicons.
 * Guarantees currentColor inheritance, consistent optical stroke width, and crisp rendering.
 */
export function HaloIcon({
  icon,
  size = "md",
  strokeWidth = 1.5,
  className,
  color = "currentColor",
  ...props
}: HaloIconProps) {
  const pixelSize = typeof size === "number" ? size : sizeMap[size] ?? 18;

  return (
    <span
      className={cn(
        "inline-flex items-center justify-center shrink-0 select-none text-current transition-colors",
        className
      )}
      style={{ width: pixelSize, height: pixelSize }}
      aria-hidden="true"
    >
      <HugeiconsIcon
        icon={icon}
        size={pixelSize}
        strokeWidth={strokeWidth}
        color={color}
        {...props}
      />
    </span>
  );
}

/**
 * HaloUI Liquid Material Design System Tokens
 * Physical optical material engine: refraction, specular highlight, optical edges,
 * neoskeuomorphic depth, tactile compression, and virtual directional lighting.
 */

:root {
  /* Surface Tints (Light Mode: Luminous warm translucent body) */
  --halo-surface: rgba(255, 255, 255, 0.72);
  --halo-surface-elevated: rgba(255, 255, 255, 0.88);
  --halo-surface-strong: rgba(255, 255, 255, 0.95);
  --halo-surface-recessed: rgba(0, 0, 0, 0.03);
  --halo-surface-tint: rgba(245, 245, 247, 0.45);

  /* Optical Edges (Light Mode: Fine micro-reflections) */
  --halo-edge: rgba(255, 255, 255, 0.9);
  --halo-edge-soft: rgba(0, 0, 0, 0.08);
  --halo-edge-bright: rgba(255, 255, 255, 1);
  --halo-edge-inner: inset 0 1px 1px 0 rgba(255, 255, 255, 0.9), inset 0 -1px 1px 0 rgba(0, 0, 0, 0.04);
  --halo-edge-outer: 0 0 0 1px rgba(0, 0, 0, 0.06);

  /* Specular Highlights (Directional: Virtual light at 135deg / top-left) */
  --halo-highlight: linear-gradient(135deg, rgba(255, 255, 255, 0.8) 0%, rgba(255, 255, 255, 0.15) 35%, rgba(255, 255, 255, 0) 100%);
  --halo-highlight-strength: 0.85;

  /* Optical Blur (Backdrop Diffusion) */
  --halo-blur-sm: 8px;
  --halo-blur-md: 16px;
  --halo-blur-lg: 28px;
  --halo-blur-xl: 44px;

  /* Shadows (Contact & Ambient anchoring) */
  --halo-shadow-contact: 0 1px 2px -0.5px rgba(0, 0, 0, 0.08), 0 2px 4px 0 rgba(0, 0, 0, 0.04);
  --halo-shadow-elevated: 0 6px 16px -4px rgba(0, 0, 0, 0.08), 0 2px 6px -1px rgba(0, 0, 0, 0.04);
  --halo-shadow-ambient: 0 16px 36px -8px rgba(0, 0, 0, 0.1);
  --halo-shadow-compressed: 0 1px 1px 0 rgba(0, 0, 0, 0.1);

  /* Refraction Parameters */
  --halo-refraction-strength: 0.12;
  --halo-refraction-offset: 1.5px;
  --halo-noise-opacity: 0.025;
  --halo-glow: rgba(0, 0, 0, 0.04);

  /* Corner Radii */
  --halo-radius-sm: 8px;
  --halo-radius-md: 12px;
  --halo-radius-lg: 18px;
  --halo-radius-xl: 26px;
  --halo-radius-full: 9999px;

  /* Focus Ring Tokens (Shared Accessibility Infrastructure) */
  --halo-focus-color: #0284c7;
  --halo-focus-offset: 2px;
  --halo-focus-width: 2px;
  --halo-focus-offset-color: #ffffff;
  --halo-focus-outer-color: rgba(2, 132, 199, 0.25);
  --halo-focus-shadow: 0 0 0 var(--halo-focus-offset) var(--halo-focus-offset-color), 0 0 0 calc(var(--halo-focus-offset) + var(--halo-focus-width)) var(--halo-focus-color), 0 0 0 calc(var(--halo-focus-offset) + var(--halo-focus-width) + 1.5px) var(--halo-focus-outer-color);

  /* Motion Presets & Timing Architecture */
  --halo-duration-micro: 120ms;
  --halo-duration-state: 180ms;
  --halo-duration-reveal: 240ms;
  --halo-duration-settle: 320ms;
  --halo-ease-tactile: cubic-bezier(0.2, 0.8, 0.3, 1);
  --halo-ease-spring: cubic-bezier(0.16, 1, 0.3, 1);
  --halo-ease-out: cubic-bezier(0, 0, 0.2, 1);

  /* Typography & Canvas (Editorial warm tone) */
  --halo-canvas: #fbfbfd;
  --halo-canvas-card: #f5f5f7;
  --halo-canvas-subtle: #eaecee;
  --halo-text-primary: #121316;
  --halo-text-secondary: #585c65;
  --halo-text-tertiary: #8b909c;
}

.dark {
  /* Surface Tints (Dark Mode: Deep graphite optical body) */
  --halo-surface: rgba(22, 23, 26, 0.7);
  --halo-surface-elevated: rgba(30, 32, 38, 0.85);
  --halo-surface-strong: rgba(38, 41, 48, 0.95);
  --halo-surface-recessed: rgba(0, 0, 0, 0.45);
  --halo-surface-tint: rgba(18, 19, 22, 0.6);

  /* Optical Edges (Dark Mode: Luminous rim catch & dark contact) */
  --halo-edge: rgba(255, 255, 255, 0.14);
  --halo-edge-soft: rgba(255, 255, 255, 0.06);
  --halo-edge-bright: rgba(255, 255, 255, 0.28);
  --halo-edge-inner: inset 0 1px 1px 0 rgba(255, 255, 255, 0.2), inset 0 -1px 1px 0 rgba(0, 0, 0, 0.6);
  --halo-edge-outer: 0 0 0 1px rgba(255, 255, 255, 0.08);

  /* Specular Highlights (Directional top-left luminescence) */
  --halo-highlight: linear-gradient(135deg, rgba(255, 255, 255, 0.22) 0%, rgba(255, 255, 255, 0.04) 38%, rgba(255, 255, 255, 0) 100%);
  --halo-highlight-strength: 0.55;

  /* Shadows (Deep graphite depth) */
  --halo-shadow-contact: 0 1px 2px -0.5px rgba(0, 0, 0, 0.4), 0 3px 6px 0 rgba(0, 0, 0, 0.3);
  --halo-shadow-elevated: 0 8px 24px -4px rgba(0, 0, 0, 0.65), 0 3px 8px -2px rgba(0, 0, 0, 0.4);
  --halo-shadow-ambient: 0 20px 48px -12px rgba(0, 0, 0, 0.85);
  --halo-shadow-compressed: 0 1px 2px 0 rgba(0, 0, 0, 0.6);

  --halo-refraction-strength: 0.18;
  --halo-noise-opacity: 0.035;
  --halo-glow: rgba(255, 255, 255, 0.04);

  /* Focus Ring Tokens (Shared Accessibility Infrastructure) */
  --halo-focus-color: #38bdf8;
  --halo-focus-offset: 2px;
  --halo-focus-width: 2px;
  --halo-focus-offset-color: #0c0d0f;
  --halo-focus-outer-color: rgba(56, 189, 248, 0.35);
  --halo-focus-shadow: 0 0 0 var(--halo-focus-offset) var(--halo-focus-offset-color), 0 0 0 calc(var(--halo-focus-offset) + var(--halo-focus-width)) var(--halo-focus-color), 0 0 0 calc(var(--halo-focus-offset) + var(--halo-focus-width) + 1.5px) var(--halo-focus-outer-color);

  /* Typography & Canvas */
  --halo-canvas: #0c0d0f;
  --halo-canvas-card: #141518;
  --halo-canvas-subtle: #1c1e22;
  --halo-text-primary: #f6f7f9;
  --halo-text-secondary: #9ea3ae;
  --halo-text-tertiary: #656a76;
}

/* Explicit Stage Scopes for Interactive Previews */
.light,
[data-stage-theme="light"] {
  --halo-surface: rgba(255, 255, 255, 0.72);
  --halo-surface-elevated: rgba(255, 255, 255, 0.88);
  --halo-surface-strong: rgba(255, 255, 255, 0.95);
  --halo-surface-recessed: rgba(0, 0, 0, 0.03);
  --halo-surface-tint: rgba(245, 245, 247, 0.45);

  --halo-edge: rgba(255, 255, 255, 0.9);
  --halo-edge-soft: rgba(0, 0, 0, 0.08);
  --halo-edge-bright: rgba(255, 255, 255, 1);
  --halo-edge-inner: inset 0 1px 1px 0 rgba(255, 255, 255, 0.9), inset 0 -1px 1px 0 rgba(0, 0, 0, 0.04);
  --halo-edge-outer: 0 0 0 1px rgba(0, 0, 0, 0.06);

  --halo-highlight: linear-gradient(135deg, rgba(255, 255, 255, 0.8) 0%, rgba(255, 255, 255, 0.15) 35%, rgba(255, 255, 255, 0) 100%);
  --halo-highlight-strength: 0.85;

  --halo-shadow-contact: 0 1px 2px -0.5px rgba(0, 0, 0, 0.08), 0 2px 4px 0 rgba(0, 0, 0, 0.04);
  --halo-shadow-elevated: 0 6px 16px -4px rgba(0, 0, 0, 0.08), 0 2px 6px -1px rgba(0, 0, 0, 0.04);
  --halo-shadow-ambient: 0 16px 36px -8px rgba(0, 0, 0, 0.1);
  --halo-shadow-compressed: 0 1px 1px 0 rgba(0, 0, 0, 0.1);

  --halo-refraction-strength: 0.12;
  --halo-noise-opacity: 0.025;
  --halo-glow: rgba(0, 0, 0, 0.04);

  --halo-focus-color: #0284c7;
  --halo-focus-offset-color: #ffffff;
  --halo-focus-outer-color: rgba(2, 132, 199, 0.25);

  --halo-canvas: #fbfbfd;
  --halo-canvas-card: #f5f5f7;
  --halo-canvas-subtle: #eaecee;
  --halo-text-primary: #121316;
  --halo-text-secondary: #585c65;
  --halo-text-tertiary: #8b909c;

  /* Scoped semantic background / foreground for light stage */
  --background: oklch(1 0 0);
  --foreground: oklch(0.145 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.145 0 0);
  --border: oklch(0.922 0 0);
  --muted-foreground: oklch(0.556 0 0);
  color-scheme: light;
}

[data-stage-theme="dark"] {
  --halo-surface: rgba(22, 23, 26, 0.7);
  --halo-surface-elevated: rgba(30, 32, 38, 0.85);
  --halo-surface-strong: rgba(38, 41, 48, 0.95);
  --halo-surface-recessed: rgba(0, 0, 0, 0.45);
  --halo-surface-tint: rgba(18, 19, 22, 0.6);

  --halo-edge: rgba(255, 255, 255, 0.14);
  --halo-edge-soft: rgba(255, 255, 255, 0.06);
  --halo-edge-bright: rgba(255, 255, 255, 0.28);
  --halo-edge-inner: inset 0 1px 1px 0 rgba(255, 255, 255, 0.2), inset 0 -1px 1px 0 rgba(0, 0, 0, 0.6);
  --halo-edge-outer: 0 0 0 1px rgba(255, 255, 255, 0.08);

  --halo-highlight: linear-gradient(135deg, rgba(255, 255, 255, 0.22) 0%, rgba(255, 255, 255, 0.04) 38%, rgba(255, 255, 255, 0) 100%);
  --halo-highlight-strength: 0.55;

  --halo-shadow-contact: 0 1px 2px -0.5px rgba(0, 0, 0, 0.4), 0 3px 6px 0 rgba(0, 0, 0, 0.3);
  --halo-shadow-elevated: 0 8px 24px -4px rgba(0, 0, 0, 0.65), 0 3px 8px -2px rgba(0, 0, 0, 0.4);
  --halo-shadow-ambient: 0 20px 48px -12px rgba(0, 0, 0, 0.85);
  --halo-shadow-compressed: 0 1px 2px 0 rgba(0, 0, 0, 0.6);

  --halo-refraction-strength: 0.18;
  --halo-noise-opacity: 0.035;
  --halo-glow: rgba(255, 255, 255, 0.04);

  --halo-focus-color: #38bdf8;
  --halo-focus-offset-color: #0c0d0f;
  --halo-focus-outer-color: rgba(56, 189, 248, 0.35);

  --halo-canvas: #0c0d0f;
  --halo-canvas-card: #141518;
  --halo-canvas-subtle: #1c1e22;
  --halo-text-primary: #f6f7f9;
  --halo-text-secondary: #9ea3ae;
  --halo-text-tertiary: #656a76;

  --background: oklch(0.145 0 0);
  --foreground: oklch(0.985 0 0);
  --card: oklch(0.145 0 0);
  --card-foreground: oklch(0.985 0 0);
  --border: oklch(0.269 0 0);
  --muted-foreground: oklch(0.708 0 0);
  color-scheme: dark;
}

/* Material Intensity Presets */
.halo-intensity-subtle {
  --halo-active-blur: var(--halo-blur-sm);
  --halo-active-highlight: 0.4;
  --halo-active-edge: 0.7;
}

.halo-intensity-balanced {
  --halo-active-blur: var(--halo-blur-md);
  --halo-active-highlight: 0.85;
  --halo-active-edge: 1;
}

.halo-intensity-rich {
  --halo-active-blur: var(--halo-blur-lg);
  --halo-active-highlight: 1.2;
  --halo-active-edge: 1.35;
}

/* Tactile Physics Classes */
.halo-tactile-press {
  transition: transform 120ms cubic-bezier(0.2, 0.8, 0.3, 1),
              box-shadow 120ms cubic-bezier(0.2, 0.8, 0.3, 1),
              background-color 150ms ease;
}

.halo-tactile-press:active:not(:disabled) {
  transform: scale(0.98) translateY(1px);
  box-shadow: var(--halo-shadow-compressed), var(--halo-edge-inner), var(--halo-edge-outer) !important;
}

/* Focus Ring Accessibility Infrastructure */
.halo-focus-ring {
  outline: none;
}

.halo-focus-ring:focus-visible {
  outline: 2px solid var(--halo-focus-color) !important;
  outline-offset: var(--halo-focus-offset) !important;
  box-shadow: var(--halo-focus-shadow) !important;
  z-index: 10;
}

/* Forced Colors (High Contrast Mode) */
@media (forced-colors: active) {
  .halo-focus-ring:focus-visible {
    outline: 2px solid Highlight !important;
    outline-offset: 2px !important;
    box-shadow: none !important;
  }
}

/* Motion Presets Classes */
.halo-motion-press {
  transition: transform var(--halo-duration-micro) var(--halo-ease-tactile),
              box-shadow var(--halo-duration-micro) var(--halo-ease-tactile);
}

.halo-motion-press:active:not(:disabled) {
  transform: scale(0.98) translateY(1px);
}

.halo-motion-lift {
  transition: transform var(--halo-duration-state) var(--halo-ease-tactile),
              box-shadow var(--halo-duration-state) var(--halo-ease-tactile);
}

.halo-motion-lift:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: var(--halo-shadow-elevated);
}

.halo-motion-reveal {
  animation: halo-reveal var(--halo-duration-reveal) var(--halo-ease-spring) forwards;
}

.halo-motion-settle {
  transition: transform var(--halo-duration-settle) var(--halo-ease-spring),
              opacity var(--halo-duration-reveal) ease;
}

.halo-motion-float {
  animation: halo-float 3.5s ease-in-out infinite alternate;
}

@keyframes halo-reveal {
  from {
    opacity: 0;
    transform: translateY(4px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes halo-float {
  0% {
    transform: translateY(0px);
  }
  100% {
    transform: translateY(-6px);
  }
}

/* Reduced Motion Override */
@media (prefers-reduced-motion: reduce) {
  .halo-tactile-press,
  .halo-motion-press,
  .halo-motion-lift,
  .halo-motion-reveal,
  .halo-motion-settle,
  .halo-motion-float,
  .halo-motion-transition {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transform: none !important;
  }
}

